    /**
     * Method to retrieve the Alert via AlertFetchOneSummary
     * @param 	summary AlertFetchOneSummary 
     * @return 	AlertFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Alert getAlert( AlertFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "AlertFetchOneSummary arg cannot be null" );
    	
    	Alert entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Alert
        	// --------------------------------------
        	CompletableFuture<Alert> futureEntity = queryGateway.query(new FindAlertQuery( new LoadAlertFilter( summary.getAlertId() ) ), ResponseTypes.instanceOf(Alert.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Alert with id " + summary.getAlertId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


